import numpy as np
from scipy.optimize import minimize

def objective(x):
    a, b = x
    c_sq = 3 - a**2 - b**2
    if c_sq < 0:
        return 1e9
    c = -np.sqrt(c_sq)
    return (a*b - c**2) * (b*c - a**2) * (c*a - b**2)

# Try a range of a and b
min_val = float('inf')
best_x = None

for a in np.linspace(0, 1.7, 100):
    for b in np.linspace(0, 1.7, 100):
        if a**2 + b**2 < 3:
            val = objective([a, b])
            if val < min_val:
                min_val = val
                best_x = (a, b)

print(f"Min found: {min_val} at {best_x}")

# Now use minimize starting from best_x
res = minimize(objective, list(best_x), method='L-BFGS-B', bounds=[(0, 1.7), (0, 1.7)])
print(f"Refined min: {res.fun} at {res.x}")

